class HashMap {
  constructor(h) {
    this.h = h;
    this.capacity = 10;
    this._size = 0;
    this.buckets = Array(this.capacity)
      .fill()
      .map(() => []);
  }

  size() {
    return this._size;
  }

  contains(k) {
    const hash = this.h(k, this.capacity);
    for (const [key, _] of this.buckets[hash]) {
      if (key === k) {
        return true;
      }
    }
    return false;
  }

  get(k) {
    const hash = this.h(k, this.capacity);
    for (const [key, val] of this.buckets[hash]) {
      if (key === k) {
        return val;
      }
    }
    return null;
  }

  add(k, v) {
    const hash = this.h(k, this.capacity);
    const bucket = this.buckets[hash];
    for (let i = 0; i < bucket.length; i++) {
      if (bucket[i][0] === k) {
        bucket[i] = [k, v];
        return;
      }
    }
    bucket.push([k, v]);
    this._size++;
    const loadFactor = this._size / this.capacity;
    if (loadFactor > 1) {
      this.resize(this.capacity * 2);
    }
  }

  remove(k) {
    const hash = this.h(k, this.capacity);
    const bucket = this.buckets[hash];
    const index = bucket.findIndex(([key, _]) => key === k);
    if (index !== -1) {
      bucket.splice(index, 1);
      this._size--;
      const loadFactor = this._size / this.capacity;
      if (loadFactor < 0.25 && this.capacity > 10) {
        this.resize(Math.floor(this.capacity / 2));
      }
    }
  }

  resize(newCapacity) {
    const newBuckets = Array(newCapacity)
      .fill()
      .map(() => []);
    for (const bucket of this.buckets) {
      for (const [k, v] of bucket) {
        const hash = this.h(k, newCapacity);
        newBuckets[hash].push([k, v]);
      }
    }
    this.buckets = newBuckets;
    this.capacity = newCapacity;
  }
}

class Multimap {
  constructor(h) {
    this.map = new HashMap(h);
    this._size = 0;
  }

  size() {
    return this._size;
  }

  contains(k) {
